// 추가 키는 각 도메인별로 같은 패턴으로 register() 호출하여 분할 가능.
// 키 명명 규칙:
//   lang.*       — 언어 메뉴 자체
//   settings.*   — 설정 모달 섹션 헤더
//   difficulty.* — 난이도 라벨
//   btn.*        — 공통 버튼 라벨
//   notify.*     — 알림 메시지
//   confirm.*    — 확인 다이얼로그 메시지
//   sidebar.*    — 사이드바 폴더 라벨
//   game.*       — 게임 타이틀·서브타이틀
//   menu.*       — 메인 메뉴 / 시작 화면
//   common.*     — 매우 빈번한 일반 단어 (예/아니오)
