  'title.unequipAllToInv':     { ko: '장착된 모든 파츠를 인벤토리로 회수', en: 'Recover all equipped parts to inventory' },
  'title.replayUrsaEnding':    { ko: '우르사 격파 엔딩 영상을 다시 시청', en: 'Replay Ursa defeat ending video' },
