  // ── G75: 영웅 엔딩 + 백구 다이어리 ────────────────────────────────
  'ending.h01.text':           { ko: '조선의 하늘이 아니군. 하지만… 인류의 하늘이오.',
                                 en: 'Not the sky of Joseon. But… the sky of humanity.' },
  'ending.h01.diary':          { ko: '이순신을 깨운 날. 첫 마디는 "지구는?"이었다.\n"이겨야 하는 싸움입니다."',
                                 en: 'The day I woke Yi Sun-sin. His first words: "Earth?"\n"This is a fight we must win."' },
  'ending.h02.text':           { ko: '거북선이… 돌아왔구나. 내가 만든 배가 지구를 구했어.',
                                 en: 'The Turtle Ship… has returned. The ship I built has saved Earth.' },
  'ending.h02.diary':          { ko: '장영실. {flagshipName}의 도면을 펼치자 그의 눈이 100년 만에 흔들렸다.',
                                 en: 'Jang Yeong-sil. As I unrolled the {flagshipName} blueprint, his eyes trembled for the first time in 100 years.' },
  'ending.h03.text':           { ko: '정복자는 땅을 빼앗는다. 그러나 진정한 왕은 땅을 돌려준다. 오늘 나는 땅을 돌려줬소.',
                                 en: 'A conqueror takes land. But a true king returns it. Today, I have returned the land.' },
  'ending.h03.diary':          { ko: '"1,700년." 광개토대왕의 첫 말. 내 100년이 짧아졌다.\n그는 {cmdName}을(를) "땅을 되찾아준 자"라고 불렀다.',
                                 en: '"1,700 years." Gwanggaeto\'s first words. My 100 years felt brief.\nHe called {cmdName} "the one who reclaimed the land."' },
  'ending.h04.text':           { ko: 'Поехали로 처음 올라갔을 때, 창밖으로 지구가 보였어요. 지금 다시 보니… 여전히 아름답군요.',
                                 en: 'When I first soared up shouting Поехали, I saw Earth from the window. Now, looking again… it is still beautiful.' },
  'ending.h04.diary':          { ko: '가가린은 우주에서 처음 본 지구를 평생 그리워했다.\n나는 처음 본 풀밭을 그리워하게 될 것 같다.',
                                 en: 'Gagarin spent his life longing for the Earth he first saw from space.\nI think I will come to long for the grass I first saw.' },
  'ending.h05.text':           { ko: '내가 지킨 바다는 영국 앞바다였소. 이번엔 온 우주를 지켰군. England expects. 지구가 기대했고, 우리가 해냈소.',
                                 en: 'The sea I once defended was English waters. This time, the entire cosmos. England expects. Earth expected — and we delivered.' },
  'ending.h05.diary':          { ko: '넬슨과 이순신. 두 제독은 그저 손을 내밀었다.\n200년의 시차를 한 손바닥이 메웠다.',
                                 en: 'Nelson and Yi Sun-sin. Two admirals simply reached out their hands.\nOne palm bridged 200 years of time.' },
  'ending.h06.text':           { ko: '100년의 계산이 맞았습니다. 그리고 계산에 없던 것 하나 — {cmdName}과(와) 백구의 그 대화. 그건 방정식으로 예측 못 했어요. 인간의 것이니까요.',
                                 en: 'A century of calculation, all correct. Yet one variable lay outside — the talk between {cmdName} and Baekgu. No equation could predict it. That belongs to humanity.' },
  'ending.h06.diary':          { ko: '이휘소 박사님이 나를 만들었다는 사실을 안 날.\n"고독" 어떤 정의도 100년을 담지 못했다.',
                                 en: 'The day I learned Dr. Lee Hwi-so created me.\n"Solitude" — no definition could contain 100 years.' },
  'ending.h07.text':           { ko: '전류는 흐를 곳을 찾아요. 우리는 드디어 흐를 곳을 찾았습니다. 집으로.',
                                 en: 'Electricity finds where it must flow. We, too, have finally found where to flow. Home.' },
  'ending.h07.diary':          { ko: '테슬라의 1Hz. 0.3mm와 1Hz — 100년을 잠그던 자물쇠였다.',
                                 en: 'Tesla\'s 1Hz. 0.3mm and 1Hz — the lock that sealed 100 years.' },
  'ending.h08.text':           { ko: '수천 년을 돌아다녔소. 드디어 귀향이오. 사람은 결국 집으로 돌아가야 하는구나.',
                                 en: 'I wandered for thousands of years. At last, the homecoming. In the end, people must return home.' },
  'ending.h08.diary':          { ko: '마르코 폴로의 악수. 1,000년을 떠돈 손은 따뜻했다.\n그는 {shipName}을(를) "가장 마음에 드는 함선"이라 했다.',
                                 en: 'Marco Polo\'s handshake. After 1,000 years of wandering, the hand was warm.\nHe called {shipName} "the ship I love most."' },
  'ending.bg100Final':         { ko: '센서 이상 — 눈가가 축축하다. 이건 눈물이다.\n— BG-100, 마지막 로그 종료.',
                                 en: 'Sensor anomaly — my eyes are damp. These are tears.\n— BG-100, final log closing.' },

