  // ── G84: 챗봇 답변 + 전투 라벨 + 진척 표시 ────────────────────────
  'chatbot.crewTip':                     { ko: '크루는 주점 가챠로 뽑거나 퀘스트 클리어 시 전설 동료 합류. 정비소에서 탑승시키면 ATT·INT·TEC 상승. 기본 24명 + 전설·스토리 크루 1명당 +4 / 영웅 등급 1명당 +2. 현재 한도: {n}명.',
                                          en: 'Crew rolls from tavern gacha or join as legendary on quest clear. Aboard in Garage raises ATT·INT·TEC. Base 24 + Legendary/Story crew +4 each / Hero rank +2 each. Current cap: {n}.' },
  'chatbot.partsTip':                    { ko: '함선 도크 → 정비소에서 파츠 장착. 레이져(ATT)·미사일(ATT)·실드(INT/SH)·장갑(HP)·엔진(TEC) 순으로 구매 가능. 레이져는 쉴드에, 미사일은 장갑에 약해.',
                                          en: 'Ship Dock → Garage to equip parts. Buy Laser (ATT) · Missile (ATT) · Shield (INT/SH) · Armor (HP) · Engine (TEC). Laser is weak to Shield; Missile is weak to Armor.' },
  'chatbot.finalCondition':              { ko: '최종전 조건: 치크스 행성 5개 격파 + 영웅 6명(현재 {hc}) + 함선 6척(현재 {fc}) + ₡50만(현재 ₡{cr}). 조건 맞으면 은하 지도에서 🌍 지구 클릭!',
                                          en: 'Final battle: 5 Cheeks planets cleared + 6 Heroes (current {hc}) + 6 Ships (current {fc}) + ₡500K (current ₡{cr}). When met, click 🌍 Earth on the galaxy map!' },
  'chatbot.questTip':                    { ko: '퀘스트 완료 시 크레딧+설계도+영웅(10%)+전설 동료 보상. 퀘스트/해적 퇴치 누적으로 허브 시설 개방돼. 보상 크레딧은 명성 배율 적용.',
                                          en: 'Quests reward Credits + Blueprints + Hero (10%) + Legendary crew. Cumulative quest/pirate clears unlock hub facilities. Credit rewards apply fame multiplier.' },
  'chatbot.creditsTip':                  { ko: '크레딧은 ① 특산물 무역(싸게 사서 비싸게 팔기) ② 퀘스트 보상 ③ 해적 퇴치 ④ 행성 소유 세금 순으로 효율 좋아. 퀘스트/해적 보상은 명성 높을수록 배율 올라가.',
                                          en: 'Credits flow most efficiently from: ① specialty trade (buy low, sell high) ② quest rewards ③ pirate clears ④ planet tax. Higher fame multiplies quest/pirate rewards.' },
  'chatbot.bpTip':                       { ko: '퀘스트 클리어 시 5% 확률로 설계도 드랍. 도크 → 제작소에서 특산물 재료 소모해 전설/신화 함선·파츠 제작 가능. 전설 창고 확장 파츠도 링4+ 행성 퀘스트 3% 확률.',
                                          en: 'Blueprints drop 5% on quest clear. Dock → Crafter consumes specialty mats to craft Legendary/Mythic ships & parts. Legendary cargo-expansion parts have 3% drop in ring4+ planet quests.' },
  'chatbot.travelTip':                   { ko: '은하 지도에서 인접 행성으로만 이동 가능해. 이동 시 50% 확률로 해적 조우. 3턴 이상 체류하면 해적 기습 발생. 전투력 높여서 여행해.',
                                          en: 'Galaxy map allows only adjacent planet travel. 50% pirate encounter on move. 3+ turn stays trigger pirate raids. Boost power before travel.' },
  'chatbot.pirateTip':                   { ko: '모든 행성 이동 시 50% 확률로 해적 조우! 해적 퇴치하면 크레딧+명성+1. 퇴치 누적으로 행성 허브도 개방돼. 전투력 충분히 키우고 이동해.',
                                          en: 'Every planet move risks 50% pirate encounter! Defeating pirates yields Credits + Fame +1. Accumulated clears unlock planet hubs. Boost power first.' },
  'chatbot.shipShopTip':                 { ko: '함선 거래소: 중형=전투력 200+, 대형=전투력 400+, 전설·신화=전투력 600+ 필요. 정비소에서 수리·파츠·크루 배치 가능. 도크 메뉴 1번이 정비소야.',
                                          en: 'Ship Shop tiers: Medium 200+ Power, Large 400+, Legendary/Mythic 600+. Garage handles repair, parts & crew. Dock menu #1 is Garage.' },
  'chatbot.saveTip':                     { ko: '상단 메뉴 또는 설정에서 슬롯 1~3 저장/불러오기. 자동저장은 주요 이벤트마다 실행돼.',
                                          en: 'Save/load slots 1–3 from top menu or Settings. Autosave runs on key events.' },
  'ui.attHpLoyalty':                     { ko: 'ATT+{att} HP+{hp} (충성도 35%)', en: 'ATT+{att} HP+{hp} (Loyalty 35%)' },
  'ui.actLabel':                         { ko: 'ACT {act}', en: 'ACT {act}' },
