  'chatbot.unknownAsk':                   { ko: '"{q}"? 그건 나도 잘 모르겠는데. 더 구체적으로 물어봐. 예: \'크레딧 버는 법\', \'영웅 영입\', \'보스 조건\'', en: '"{q}"? I\'m not sure. Try being more specific. e.g.: "how to earn credits", "hero recruit", "boss conditions"' },
