  'ui.atkPlus':                          { ko: '⚔️ 공격력 +{n}', en: '⚔️ ATK +{n}' },
  'story.ring1Open':                     { ko: '{nm}, 이제 1링 적대 행성들(보라색)이 열렸어. TOI-700d, 케플러-452b, 우르사-알파 — 거기서 싸워야 해.',
                                          en: '{nm}, Ring 1 hostile planets (purple) are open now. TOI-700d, Kepler-452b, Ursa-Alpha — fight there.' },
  'story.intro':                         { ko: '{nm}은(는) 우르사 메이저가 이끄는 치크스 봉쇄 함대에 지구가 갇히던 날, 낡은 머스탱 한 척으로 첫 항해에 나섰다. {co}의 깃발 아래 항로를 개척해 자금을 모으고, 잔해를 뒤져 부품을 건지고, 적을 격파하며 한 척 한 척 함대를 키웠다. 곁에는 언제나 AI 동료 백구가 있었다. 가슴에 새긴 목표는 단 하나 — 인류를 옥죄는 봉쇄를 부수고, 푸른 지구를 되찾는 것.',
                                          en: 'On the day Earth was trapped by Ursa Major\'s Cheeks blockade fleet, {nm} set out on their first voyage in an old Mustang. Under {co}\'s flag they pioneered routes, gathered funds, scavenged wreckage for parts, and grew their fleet ship by ship through battle. AI companion Baekgu was always at their side. The single goal carved on their chest — break the blockade strangling humanity, and reclaim the blue Earth.' },
  'story.finalStep':                     { ko: '{nm}, 드디어 이 순간이 왔어. 지구 봉쇄를 푸는 마지막 단계야.', en: '{nm}, the moment has come. The final step to lift the Earth blockade.' },
  'story.postUrsa':                      { ko: '{nm}, 우르사 메이저는 무너졌지만 우주는 여전히 위험해. 치크스 잔당과 보이드 균열도 정리해야 해.', en: '{nm}, Ursa Major has fallen, but space is still dangerous. The Cheeks remnants and Void rifts must be cleaned up too.' },
  'ui.enhanceSuccess':                   { ko: '🎉 +{lv} 강화 성공!', en: '🎉 +{lv} Enhance Success!' },
  'ui.enhanceSubline':                   { ko: '{nm} · 능력치 +{pct}%', en: '{nm} · Stats +{pct}%' },
  'ui.slotHasDataOverwrite':             { ko: '슬롯 {n}에 이미 저장된 데이터가 있습니다. 덮어쓸까요?', en: 'Slot {n} already has saved data. Overwrite?' },
