  'baekgu.tollPaidSafe':         { ko: '통행세 내고 무사 통과! 안전이 최우선이지~',
                                   en: 'Paid the toll and passed safely! Safety first~' },

  // ── G10-A: 추가 baekgu() 정적 대사 19종 ─────────────────────────────
  'baekgu.asteroidBelt':         { ko: '소행성대 돌파야! 방향키나 마우스로 회피, Shift로 레이저, Ctrl로 미사일! 50초 버텨!',
                                   en: 'Asteroid belt breach! Dodge with arrow keys or mouse, Shift for lasers, Ctrl for missiles! Hold out 50 seconds!' },
  'baekgu.blackHoleEntry':       { ko: '블랙홀로 가는 진입로는 치크스(적대) 행성 근처에서만 열려. 치크스 행성이나 그 인접 행성으로 이동한 뒤 다시 시도해.',
                                   en: 'The black-hole entry only opens near hostile Chiks planets. Move to a Chiks planet or an adjacent one and try again.' },
  'baekgu.blackHoleGateLocked':  { ko: '저긴 은하 중심의 블랙홀... 먼저 지구를 해방(우르사 메이저 격파)해야 실마리가 잡힐 거야.',
                                   en: 'That is the black hole at the galactic core... You need to liberate Earth (defeat Ursa Major) first to get a lead.' },
  'baekgu.earthApproachA':       { ko: '지구다... 우르사 메이저가 우리를 기다리고 있어. 모든 화력 준비!',
                                   en: 'Earth ahead... Ursa Major is waiting for us. Ready all firepower!' },
  'baekgu.earthBlockedShort':    { ko: '지구는 봉쇄됐어. ACT 3에 도달해야 진입할 수 있어!',
                                   en: 'Earth is blockaded. You must reach ACT 3 to enter!' },
  'baekgu.earthApproachB':       { ko: '지구다... 우르사 메이저가 기다린다. 모든 화력 준비!',
                                   en: 'Earth ahead... Ursa Major awaits. Ready all firepower!' },
  'baekgu.resistanceZoneHint':   { ko: '이 구역은 지구 저항군 지역이야. 상점에서 난중일기 영인본 구입하면 이순신 영입 가능해.',
                                   en: 'This sector is Earth Resistance territory. Buy a copy of Nanjung Ilgi at the shop to recruit Yi Sun-shin.' },
  'baekgu.nanjungHave':          { ko: '난중일기 있어. 이 행성에 이순신이 있으면 영입 가능해.',
                                   en: 'You have Nanjung Ilgi. If Yi Sun-shin is on this planet, you can recruit him.' },
  'baekgu.retreatedStep':        { ko: '한발 물러섰어. 충분히 강해진 후 다시 도전해도 돼.',
                                   en: 'Backed off a step. You can challenge again once strong enough.' },
  'baekgu.tollPaidPrideHit':     { ko: '통행료 냈어. 자존심은 상하지만 함선은 멀쩡하잖아. 다음엔 박살내자.',
                                   en: 'Paid the toll. Pride hurts, but at least the ship is intact. Next time we crush them.' },
  'baekgu.fledStronger':         { ko: '도망쳤어. 다음엔 더 강해진 다음에 부딪치자.',
                                   en: "We fled. Let's hit them after we get stronger." },
  'baekgu.haikjin':              { ko: '학익진이다! 함대가 양 날개로 포위! 적을 가운데로 몰아넣어. 화력 3배 폭격!',
                                   en: 'Crane Wing Formation! Fleet flanks both wings! Drive the enemy to the center. Triple firepower barrage!' },
  'baekgu.einsteinRelativity':   { ko: '아인슈타인의 상대성 이론! 시간축이 휘어진다! 적은 한 번 맞는데 우린 네 번 친다.',
                                   en: "Einstein's Relativity! Time bends! Enemies hit once while we strike four times." },
  'baekgu.teslaHyperspace':      { ko: '테슬라의 전자기 초공간! 함선 무기가 번개로 변했어! 폭딜의 시작!',
                                   en: "Tesla's electromagnetic hyperspace! Ship weapons turn to lightning! The burst-damage begins!" },
  'baekgu.genesisImpact':        { ko: '제네시스 임펙트! 영웅들의 의지가 한 점에 모였어! 적은 시공간에서 사라진다.',
                                   en: 'Genesis Impact! The heroes\' wills converge on one point! Enemies vanish from space-time.' },
  'baekgu.destinationEarth':     { ko: '데스티네이션 어스!! 8명 영웅의 의지 + 100년 봉쇄를 깬 인류의 분노! 화력 10배! 적은 사라진다 — 우주의 정의를 보여줘!',
                                   en: 'Destination Earth!! The will of 8 heroes + the fury of humanity that broke a century of blockade! 10× firepower! The enemy is gone — show them the justice of the cosmos!' },
  'baekgu.voidPhaseUnlocked':    { ko: '보이드 페이즈 강제 해금됨. 제타 레티쿨리(P30)로 이동해서 광장 → 제독 의뢰 확인해봐!',
                                   en: 'Void phase force-unlocked. Travel to Zeta Reticuli (P30), then check the Plaza → Admiral commission!' },
  'baekgu.voidSpearGranted':     { ko: '보이드가 마지막 시험을 위해 ✦ 보이드의 창을 남겼어. 정비소에서 함선에 장착해 — 최종 결전에서 1대씩 즉시 파괴 가능해.',
                                   en: "The Void left ✦ the Void Spear for the final trial. Mount it at the garage — it lets you instantly destroy one enemy at a time in the final showdown." },
  'baekgu.mirrorFleetAwoken':    { ko: '보이드가 인류 역사상 가장 위대한 5척을 깨워냈어! 능력치는 동일, HP는 두 배. 우리 전술이 답이다 — 일점사부터!',
                                   en: "The Void has awakened the five greatest ships in human history! Same stats, double HP. Our tactics are the answer — start with focus-fire!" },

  // 확인 다이얼로그
