  'hero.npc.parksoi.nm':        { ko: '박소이',           en: 'Park So-i' },
  'hero.npc.leekangho.nm':      { ko: '이강호',           en: 'Lee Kang-ho' },
  'hero.npc.junghayeon.nm':     { ko: '정하연',           en: 'Jung Ha-yeon' },
