  'hero.npc.carlossilva.nm':    { ko: '카를로스 실바',    en: 'Carlos Silva' },
  'hero.npc.mariagonzalez.nm':  { ko: '마리아 곤잘레스',  en: 'Maria Gonzalez' },
  'hero.npc.rashidaltariq.nm':  { ko: '라시드 알타리크',  en: 'Rashid al-Tariq' },
  'hero.npc.fatimaalnajjar.nm': { ko: '파티마 알나자르',  en: 'Fatima al-Najjar' },
  'hero.npc.tylerchen.nm':      { ko: '타일러 첸',        en: 'Tyler Chen' },
  'hero.npc.omaralfaruq.nm':    { ko: '오마르 알파루크',  en: 'Omar al-Faruq' },
  'hero.npc.sergeivolkov.nm':   { ko: '세르게이 볼코브',  en: 'Sergei Volkov' },
  'hero.npc.diegoramirez.nm':   { ko: '디에고 라미레스',  en: 'Diego Ramirez' },
  'hero.npc.hanminseok.nm':     { ko: '한민석',           en: 'Han Min-seok' },
  'hero.npc.choiyoungjun.nm':   { ko: '최영준',           en: 'Choi Young-jun' },

