  'part.S15.nm':   { ko: '신의 방패',     en: 'God\'s Shield' },
  'part.S15.desc': { ko: '전설 실드. 매 턴 maxSH 8% 자가 충전',
                     en: 'Legendary shield. Self-charges 8% maxSH per turn.' },
  // 장갑 A
  'part.A01.nm':   { ko: '기본 합금',     en: 'Basic Alloy' },
  'part.A01.desc': { ko: '기초 장갑',     en: 'Basic armor.' },
  'part.A04.nm':   { ko: '티타늄 장갑',   en: 'Titanium Armor' },
  'part.A04.desc': { ko: '중급 장갑',     en: 'Mid-tier armor.' },
  'part.A08.nm':   { ko: '중성자 장갑',   en: 'Neutron Armor' },
  'part.A08.desc': { ko: '고급 장갑',     en: 'High-tier armor.' },
  'part.A12.nm':   { ko: '위상 장갑',     en: 'Phase Armor' },
  'part.A12.desc': { ko: '최고급 장갑',   en: 'Top-tier armor.' },
  'part.A15.nm':   { ko: '절대 방벽',     en: 'Absolute Barrier' },
  'part.A15.desc': { ko: '전설 장갑',     en: 'Legendary armor.' },
  // 엔진 E
  'part.E01.nm':   { ko: '이온 추진기',   en: 'Ion Thruster' },
  'part.E01.desc': { ko: '기초 엔진',     en: 'Basic engine.' },
  'part.E04.nm':   { ko: '플라즈마 드라이브', en: 'Plasma Drive' },
  'part.E04.desc': { ko: '중급 엔진',     en: 'Mid-tier engine.' },
  'part.E08.nm':   { ko: '양자 드라이브', en: 'Quantum Drive' },
  'part.E08.desc': { ko: '고급 엔진',     en: 'High-tier engine.' },
  'part.E12.nm':   { ko: '하이퍼드라이브', en: 'Hyperdrive' },
  'part.E12.desc': { ko: '최고급 엔진',   en: 'Top-tier engine.' },
  'part.E15.nm':   { ko: '블링크 엔진',   en: 'Blink Engine' },
  'part.E15.desc': { ko: '전설 엔진. 순간이동', en: 'Legendary engine. Teleport.' },
  // 미사일 ML
  'part.ML01.nm':   { ko: '타우 미사일',  en: 'Tau Missile' },
  'part.ML01.desc': { ko: '[F06 지구저항군] 이강호 박사 개발. 게릴라전용 경량 열추적 미사일. 실드 약세 / 장갑 관통 특화.',
                     en: '[F06 Earth Resistance] Developed by Dr. Lee Kang-ho. Lightweight heat-seeking missile for guerrilla warfare. Weak against shields / specialized in armor penetration.' },
  'part.ML02.nm':   { ko: '크리그 충격탄', en: 'Krieg Shock Round' },
  'part.ML02.desc': { ko: '[F04 크리그] 화산 마그마 코어 폭발 에너지 탄두. 기원지대 전쟁영주 카를로스 승인. 장갑 파괴 전문.',
                     en: '[F04 Krieg] Volcanic magma-core explosive warhead. Approved by Warlord Carlos of the origin zone. Armor-destruction specialist.' },
  'part.ML03.nm':   { ko: '보이드 파동탄', en: 'Void Pulse Round' },
  'part.ML03.desc': { ko: '[F07 보이드] 반물질 탄두로 공간 왜곡. 라시드 알타리크 연구소 개발. 거리 무관 명중률.',
                     en: '[F07 Void] Antimatter warhead that warps space. Developed by Rashid al-Tariq\'s lab. Accuracy unaffected by distance.' },
  'part.ML04.nm':   { ko: '수퍼비아 중력 미사일', en: 'Superbia Gravity Missile' },
  'part.ML04.desc': { ko: '[F01 수퍼비아] 소피아 모렐 설계. 중력 집속 탄두. 명중 시 적 ENG -20% (1턴 지속).',
                     en: '[F01 Superbia] Designed by Sofia Morel. Gravity-focusing warhead. On hit: enemy ENG -20% (1 turn).' },
  'part.ML05.nm':   { ko: '메카니카 스마트 미사일', en: 'Mechanica Smart Missile' },
  'part.ML05.desc': { ko: '[F03 메카니카] AI 자율유도. 드미트리 개발. 회피 중인 함선도 추적 명중.',
                     en: '[F03 Mechanica] AI-autonomous guidance. Developed by Dmitri. Tracks and hits even evading ships.' },
  'part.ML06.nm':   { ko: '아우레우스 황금 작살 ⚡전설', en: 'Aureus Gold Harpoon ⚡Legend' },
  'part.ML06.desc': { ko: '[F02 아우레우스] 전설급 유도 작살. 피에르 발주. 태양핵 에너지 탄두로 DEF 무시 관통 효과.',
                     en: '[F02 Aureus] Legendary guided harpoon. Commissioned by Pierre. Solar-core energy warhead pierces DEF.' },
  'part.ML07.nm':   { ko: '치크스 결정 파쇄탄 ⚡전설', en: 'Chiks Crystal Frag Round ⚡Legend' },
  'part.ML07.desc': { ko: '[F05 치크스] 결정석 초고속 파편 미사일. 타기가 제작. 폭발 반경 3칸 광역 타격.',
                     en: '[F05 Chiks] Hyper-velocity crystalstone-shard missile. Crafted by Tagigga. 3-tile AoE blast.' },
  'part.MMB01.nm':   { ko: '이휘소 방정식 미사일 ❖신화', en: 'Lee Hwi-soh Equation Missile ❖Mythic' },
