  'part.RB05.nm':   { ko: '자가 복구 매트릭스 ✦신화', en: 'Self-Repair Matrix ✦Mythic' },
  'part.RB05.desc': { ko: '신화 자가 복구 매트릭스. 매 턴 maxHP 15% 회복 + 격침 시 1회 부활(HP 30%). 상점 미판매.',
                     en: 'Mythic self-repair matrix. Restores 15% maxHP per turn + revives once on destruction (HP 30%). Not sold in shops.' },
  // 흡혈형 자동 수리 로봇 (5종)
  'part.RB06.nm':   { ko: '흡혈 정비 드론', en: 'Vampiric Maintenance Drone' },
  'part.RB06.desc': { ko: '적의 에너지 잔열을 회수하는 정비 드론. 매 턴 maxHP 3% 회복 + 레이저 발사 시 피해의 5%만큼 HP 흡수',
                     en: 'Maintenance drone that drains residual enemy energy. Restores 3% maxHP per turn + on laser fire: drains 5% of damage as HP.' },
  'part.RB07.nm':   { ko: '적응형 회복 봇', en: 'Adaptive Recovery Bot' },
  'part.RB07.desc': { ko: '중급 적응형 회복 봇. 매 턴 maxHP 5% 회복 + 레이저 발사 시 피해의 8%만큼 HP / 5%만큼 실드 흡수',
                     en: 'Mid-tier adaptive recovery bot. Restores 5% maxHP per turn + on laser fire: drains 8% HP / 5% shield of damage.' },
  'part.RB08.nm':   { ko: '듀얼 코어 정비 시스템', en: 'Dual-Core Maintenance System' },
  'part.RB08.desc': { ko: '영웅급 듀얼 코어 정비 시스템. 매 턴 maxHP 8% 회복 + 레이저 발사 시 피해의 10%만큼 HP / 8%만큼 실드 흡수',
                     en: 'Hero-grade dual-core maintenance system. Restores 8% maxHP per turn + on laser fire: drains 10% HP / 8% shield of damage.' },
  'part.RB09.nm':   { ko: '흡혈 폭격 코어 ⚡전설', en: 'Vampiric Strike Core ⚡Legend' },
  'part.RB09.desc': { ko: '전설 흡혈 코어. 매 턴 maxHP 12% 회복 + 레이저 발사 시 피해의 15%만큼 HP / 12%만큼 실드 흡수. 상점 미판매 (설계도 제작)',
                     en: 'Legendary vampiric core. Restores 12% maxHP per turn + on laser fire: drains 15% HP / 12% shield of damage. Not sold in shops (blueprint craft).' },
  'part.RB10.nm':   { ko: '영혼 흡수 매트릭스 ✦신화', en: 'Soul Absorption Matrix ✦Mythic' },
  'part.RB10.desc': { ko: '신화 영혼 흡수 매트릭스. 매 턴 maxHP 18% 회복 + 레이저 발사 시 피해의 20%만큼 HP / 18%만큼 실드 흡수. 격침 시 1회 부활(HP 50%). 상점 미판매 (설계도 제작)',
                     en: 'Mythic soul-absorption matrix. Restores 18% maxHP per turn + on laser fire: drains 20% HP / 18% shield of damage. Revives once on destruction (HP 50%). Not sold in shops (blueprint craft).' },

