  // 영웅 영입 인사말
  'heroGreet.H01':          { ko: '조선의 바다는 저물었으나, 지켜야 할 바다는 여전히 많구려. 사령관, 그 싸움 내가 맡으리다.',
                              en: 'Joseon\'s seas may have set, but seas worth defending remain many. Commander, leave that fight to me.' },
  'heroGreet.H02':          { ko: '오, 이 함선의 설계도… 손볼 곳이 한두 군데가 아닙니다. 제게 맡겨 주시겠습니까, 사령관?',
                              en: 'Oh, this ship\'s blueprint... plenty to tune. Leave it to me, Commander?' },
  'heroGreet.H03':          { ko: '이 광활한 우주가 전부 미개척지란 말인가! 사령관, 정복할 별을 보여다오.',
                              en: 'All this vast space, unexplored?! Commander, show me the stars to conquer.' },
  'heroGreet.H04':          { ko: '다시 우주로 나갈 수 있다니… Поехали! 갑시다, 사령관!',
                              en: 'I can go to space again... Poyekhali! Let\'s go, Commander!' },
  'heroGreet.H05':          { ko: 'England expects… 아니, 이제는 온 인류가 기대하는군. 이 함대, 내가 맡지.',
                              en: 'England expects... no, all humanity expects now. I\'ll take this fleet.' },
  'heroGreet.H06':          { ko: '흥미롭군요. 시간과 공간을 가르는 항해라… 계산이 맞다면, 우리는 반드시 이깁니다.',
                              en: 'Fascinating. A voyage that splits time and space... if my math is right, we will surely win.' },
  'heroGreet.H07':          { ko: '전류는 흐를 곳을 찾기 마련이죠. 나의 번개를 적에게 흘려보내 드리겠습니다.',
                              en: 'Current finds its path. I shall send my lightning to the enemy.' },
  'heroGreet.H08':          { ko: '가보지 않은 항로가 저토록 많은데 가만히 있으라고요? 사령관, 어서 떠납시다!',
                              en: 'So many uncharted routes — and you want to stay still? Commander, let\'s set sail!' },
  // 맵 안내
  'map.help':               { ko: '[🖱️ 좌클릭→이동  우클릭→3D회전  휠→줌  행성클릭→선택]',
                              en: '[🖱️ L-click→move  R-click→3D rotate  Wheel→zoom  Click planet→select]' },
  // 팩션 도감 설명
