  // 통행료 적 NPC
  'toll.boss.hook':         { ko: '해적 두목 「철갈고리」 보그', en: 'Pirate Boss "Iron Hook" Borg' },
  'toll.boss.hookLine':     { ko: '어이 거기 함대. 이 항로는 내 구역이야. 통행료 ₡{X}만 내놓으면 곱게 보내주지.',
                              en: 'Hey, fleet! This route is my turf. Pay a toll of ₡{X} and I\'ll let you pass.' },
  'toll.boss.karim':        { ko: '밀수왕 카림',         en: 'Smuggler King Karim' },
  'toll.boss.karimLine':    { ko: '오, 함선들 좋은데? 흠집 내기 싫으면 ₡{X}만 내. 사업은 사업이니까.',
                              en: 'Oh, nice ships. If you don\'t want scratches, pay ₡{X}. Business is business.' },
  'toll.boss.krash':        { ko: '치크스 군단장 크라쉬', en: 'Chiks Commander Krash' },
  'toll.boss.krashLine':    { ko: '인간 주제에 감히 여기까지. 목숨값으로 ₡{X}를 바쳐라. 그럼 오늘은 살려두마.',
                              en: 'Humans daring to come this far. Pay ₡{X} for your lives — I\'ll spare you today.' },
  'toll.boss.veil':         { ko: '현상금 사냥꾼 베일',  en: 'Bounty Hunter Veil' },
  'toll.boss.veilLine':     { ko: '네 목에 걸린 현상금보다 ₡{X}가 싸게 먹히겠지? 자, 선택해.',
                              en: '₡{X} is cheaper than the bounty on your head, isn\'t it? Choose.' },
  'toll.boss.dorga':        { ko: '약탈자 도르가',       en: 'Raider Dorga' },
  'toll.boss.dorgaLine':    { ko: '함선이 아깝지 않냐? ₡{X} 내면 못 본 척 해주마. 거절하면… 후회할걸.',
                              en: 'Don\'t you care about your ships? Pay ₡{X} and I look away. Refuse... you\'ll regret it.' },
