  // 우르사 인트로
  'ursa.fightEnter':        { ko: '⚔️ 전투 돌입!',      en: '⚔️ Enter Battle!' },
  'ursa.intro.sys1':        { ko: '⚠️ 워프 신호 감지... 우르사 메이저 함대 출현. 호위 친위대 15척 확인.',
                              en: '⚠️ Warp signal detected... Ursa Major fleet appears. 15 elite escorts confirmed.' },
  'ursa.intro.ursa1':       { ko: '... 인류의 작은 함대가 마침내 여기까지 왔는가.',
                              en: '... Humanity\'s small fleet has finally come this far.' },
  'ursa.intro.ursa2':       { ko: '100년 전, 우리는 너희 별을 봉인했다. 너희의 침묵은 영원할 줄 알았지.',
                              en: '100 years ago, we sealed your star. We thought your silence would last forever.' },
