  'hof.unnamed':            { ko: '무명',               en: 'Anonymous' },
  'hof.globalLoading':      { ko: '🌐 글로벌 명예의 전당 불러오는 중... (최대 15초)',
                              en: '🌐 Loading global Hall of Fame... (up to 15s)' },
  // 피드백
  'feedback.copyBtn':       { ko: '📋 복사하기',        en: '📋 Copy' },
  'feedback.sendBtn':       { ko: '📧 메일 보내기',     en: '📧 Send by Email' },
  // 치트
  'cheat.confirmBtn':       { ko: '🔓 확인',            en: '🔓 OK' },
  // 백업 prompt
  'backup.slotPrompt':      { ko: '어느 슬롯에 복원하시겠습니까? (1~8, 기본 1)',
                              en: 'Which slot do you want to restore? (1-8, default 1)' },
  // 백업 commander fallback
  'backup.commander':       { ko: 'commander',          en: 'commander' },
  // 우르사 인트로 추가
  'ursa.intro.cmd1':        { ko: '그 봉쇄, 오늘로 끝이다. 100년의 빚, 지금 갚는다.',
                              en: 'That blockade ends today. The hundred-year debt — paid right now.' },
  'ursa.intro.ursa3':       { ko: '대담하군. 그러나 너희가 본 것은 우리의 그림자뿐. 진짜 모습을 보여주마.',
                              en: 'Bold. But what you saw was our shadow. I\'ll show you the true form.' },
  'ursa.intro.ursa4':       { ko: '친위대 알파, 베타, 감마, 델타, 엡실론 — 전열을 정비하라!',
                              en: 'Alpha, Beta, Gamma, Delta, Epsilon escorts — form the battle line!' },
  'ursa.intro.bk':          { ko: '전투력 1천만! 호위함대까지! 진짜 큰 거 왔어 — 모든 화력을 쏟아부어!',
                              en: 'Ten million power! Plus escorts! The real big one — pour every gun on them!' },
  'ursa.intro.cmd2':        { ko: '전 함대, 전열 정비. 첫 일격으로 결판낸다. 발사!',
                              en: 'All hands, form ranks. End it with the first strike. Fire!' },
  'ursa.startFinalBattle':  { ko: '⚔️ 최종 전투 시작', en: '⚔️ Start Final Battle' },
  'ursa.later':             { ko: '잠시 후',             en: 'Later' },
  'ursa.bossName':          { ko: '우르사 메이저',       en: 'Ursa Major' },
  'ursa.phase2Line':        { ko: '인상적이다.. 하지만 아직 끝나진 않았다. 자.. 한번 막아보아라!',
                              en: 'Impressive... but it\'s not over. Now... try to stop this!' },
  // 우르사 격파 후 블랙팔콘 출현
  'falcon.afterUrsa':       { ko: '훌륭하다... 내 함대를 모두 꺾었군. 1000년 만에 처음이다. 그렇다면 — 이제 내가 직접 상대해주지.',
                              en: 'Excellent... you broke my whole fleet. The first in a thousand years. Then — I\'ll face you myself.' },
  // 우르사 outro
  'ursa.outro.1':           { ko: '... 불가능... 한낱 인간들의 함대가... 100년의 봉인을... 깨버렸단 말인가...',
                              en: 'Impossible... a mere human fleet... broke the 100-year seal...?' },
  'ursa.outro.2':           { ko: '...크윽... 인정하지... 너희에게는 — 우리가 갖지 못한 그 무엇이 있었다...',
                              en: '...Khh... I admit it... you had something we did not...' },
  'ursa.outro.3':           { ko: '고향으로... 돌아가야 할 이유. 인류의... 그 강한 의지... 그것이 우리를... 무너뜨렸다...',
                              en: 'A reason to return home... humanity\'s strong will... it broke us...' },
  'ursa.outro.sys1':        { ko: '💥 적 기함 우르사 메이저 — 코어 붕괴 확인. 친위대 전멸. 워프 신호 소실.',
                              en: '💥 Enemy flagship Ursa Major — core collapse confirmed. Escorts destroyed. Warp signal lost.' },
  'ursa.outro.bk':          { ko: '지구 봉쇄가 풀린다! 통신 신호가 들어와! 가족들이... 사람들이... 다시 별을 본대!',
                              en: 'The Earth blockade lifts! Comms incoming! Families... people... see the stars again!' },
  'ursa.outro.sys2':        { ko: '📡 지구 통신망 복구. 전 인류로부터의 환호가 은하 전체로 송신되고 있습니다.',
                              en: '📡 Earth comms restored. Cheers from all humanity broadcast across the galaxy.' },
  'ursa.outro.cmd1':        { ko: '...드디어 끝났다. 100년의 침묵, 100년의 굴종 — 오늘 우리 손으로 청산했다.',
                              en: '...It\'s over. 100 years of silence, 100 years of submission — settled by our own hands today.' },
  'ursa.outro.cmd2':        { ko: '고생했다, 전 함대. 영웅들, 크루들 — 너희 모두의 이름은 인류 역사에 영원히 새겨질 것이다.',
                              en: 'Well done, fleet. Heroes, crew — your names are forever in humanity\'s history.' },
  'ursa.outro.cmd3':        { ko: '우리는 인류의 길을 열었다. 이제부터 별들은 우리의 친구다 — 그리고 지구는, 영원히 자유다.',
                              en: 'We opened humanity\'s path. From now on, the stars are our friends — and Earth is free forever.' },
  'ursa.outro.sys3':        { ko: '🌍 지구 봉쇄 완전 해제. 인류 해방 선언. — DESTINATION EARTH 완수.',
                              en: '🌍 Earth blockade fully lifted. Humanity liberation declared. — DESTINATION EARTH completed.' },
  // outro 모달 버튼
  'outro.confirmReward':    { ko: '🎊 보상 확인 ▶',     en: '🎊 Confirm Reward ▶' },
  'outro.reportConfirm':    { ko: '🎁 전투 보고서 확인 ▶', en: '🎁 Confirm Battle Report ▶' },
  'outro.closeBtn':         { ko: '닫기 →',              en: 'Close →' },
