  'credits.act1Body':       { ko: '100년의 봉쇄. 우르사 메이저 함대가 지구를 둘러쌌고, 위장 상단 {co}이(가) 폐지를 주워가며 함대를 일군다. 백구가 {cmd}을(를) 깨운다.',
                              en: 'A 100-year blockade. Ursa Major\'s fleet ringed Earth, while the front-shop {co} scraped together credits and ships from scrap. Baekgu wakes {cmd}.' },
  'credits.act2Body':       { ko: '일곱 팩션의 우주. 수퍼비아, 아우레우스, 메카니카, 크리그, 치크스, 지구 저항군, 보이드. {cmd}은(는) 무역과 전투로 함대를 키우고, 전설의 영웅 {n}명을 영입한다.',
                              en: 'A galaxy of seven factions — Superbia, Aureus, Mechanica, Krieg, Cheeks, Earth Resistance, Void. {cmd} grew the fleet through trade and combat, and recruited {n} legendary heroes.' },
  'credits.act3Body':       { ko: '균열의 너머. 보이드 행성에서 미지의 신호가 잡힌다. 보이드 크리스탈을 모으며 최종전을 준비한다.',
                              en: 'Beyond the fissure. Unknown signals reach us from the Void planets. We gather Void Crystals and prepare for the final battle.' },
  'credits.act4Body':       { ko: '지구 해방. 우르사 메이저 격파. 100년의 봉쇄가 끝나고, 인류는 다시 우주로 나간다.',
                              en: 'Earth Liberation. Ursa Major is broken. After a century, the blockade ends — and humanity takes to the stars again.' },
  'credits.act5Body':       { ko: '보이드의 심연. 1000년의 침묵을 깬 블랙팔콘과의 결투. 모든 시련을 견뎌낸 사령관은 은하 가운데 블랙홀로 들어간다.',
                              en: 'The Void Abyss. A duel with Black Falcon, who broke 1,000 years of silence. After every trial, the commander steps into the black hole at the heart of the galaxy.' },
  'credits.voidQuote':      { ko: '"누구도 여기서 살아서 나가지 못한다.<br>네가 원하는걸 해라."',
                              en: '"No one walks out of here alive.<br>Do as you wish."' },
  // 엔딩 6막 헤더/본문
  'ending.prologueHead':    { ko: '— 프롤로그 · 봉쇄의 100년 —', en: '— PROLOGUE · THE CENTURY OF BLOCKADE —' },
  'ending.act1Head':        { ko: '— 제1막 · 각성 —',           en: '— ACT I · AWAKENING —' },
  'ending.act2Head':        { ko: '— 제2막 · 변경의 불길 —',    en: '— ACT II · FIRES OF THE FRONTIER —' },
  'ending.act3Head':        { ko: '— 제3막 · 잠든 영웅들 —',    en: '— ACT III · SLEEPING HEROES —' },
  'ending.act4Head':        { ko: '— 제4막 · 치크스의 진실 —',  en: '— ACT IV · THE TRUTH OF THE CHEEKS —' },
  'ending.act5Head':        { ko: '— 제5막 · 지구 해방 —',      en: '— ACT V · EARTH LIBERATION —' },
  'ending.act6Head':        { ko: '— 제6막 · 보이드의 심연 —',  en: '— ACT VI · THE VOID ABYSS —' },
  'ending.act6Body':        { ko: '우르사가 남긴 한 마디는 좌표였다. 그곳에는 별빛이 닿지 않는 검은 균열이 있었고, 단 한 줄의 메시지가 떠 있었다. — <i style="color:#fff">"누구도 여기서 살아서 나가지 못한다. 네가 원하는 걸 해라."</i> 우리는 갔다. 알면서도 갔다. 그것이 인간의 방식이었다. 그리고 우리는 — 돌아왔다.',
                              en: 'Ursa\'s final word was a coordinate. There, where starlight could not reach, lay a black fissure with a single line waiting: — <i style="color:#fff">"No one walks out of here alive. Do as you wish."</i> We went. Knowing — and yet we went. That is the human way. And we — returned.' },
  'ending.epilogueHead':    { ko: '— 에필로그 · 귀향 —',        en: '— EPILOGUE · HOMECOMING —' },
  'ending.epilogueBody':    { ko: 'D-day 100년 + 412일. {ship}은(는) 지구의 풀밭 위에 안착했다. 100년 형광등이 흉내 못 한 색이 사령관의 눈에 비쳤고, 백구의 센서엔 처음 보는 액체가 흘렀다. — 인류는 다시 별을 향해 손을 뻗는다. 이번엔 그 손을 거두지 않는다.',
                              en: 'D-Day, 100 years + 412 days. {ship} settled onto Earth\'s grass. Colors no fluorescent lamp had matched in a century filled the commander\'s eyes; an unfamiliar liquid flowed across Baekgu\'s sensors. — Humanity reaches for the stars once more. This time, we will not pull the hand back.' },
